#include <iostream>
#include <vector>
using namespace std;

int main() {
    int n;
    cin >> n;
    vector<int> p(n);
    for (int i = 0; i < n; i++) cin >> p[i];
    int ans = 0;
    for (int i = 0; i < n; i++) {
        int sum = 0;
        for (int j = i; j < n; j++) {
            sum += p[j];
            int len = j - i + 1;
            for (int k = i; k <= j; k++) {
                if (p[k] * len == sum) {
                    ans++;
                    break;
                }
            }
        }
    }
    cout << ans << '\n';
    return 0;
}

